import { Component, createEffect, createSignal, Show } from "solid-js";

import { getPlayerColorVariants, isPrimaryColorLighter } from "#core/ui/utilities/utilities-color.js";
import { Icon } from "#core/ui/utilities/utilities-image.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { PortraitIcon } from "#core/ui-next/components/portrait-icon.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { getSettlementIconInfo } from "#core/ui-next/utilities/settlement-utilities.js";

export interface LeaderTileData {
	leaderId: number;
	size: number;
	cityId?: ComponentID;
	representsCityState?: boolean;
	showBanner?: boolean;
}

export const PlotTooltipPlayerPortrait: Component<LeaderTileData> = (props) => {
	const [bannerColor, setBannerColor] = createSignal<string>("");
	const [civSymbol, setCivSymbol] = createSignal<string>("");
	const [civSymbolColor, setCivSymbolColor] = createSignal<string>("");
	const [settlementName, setSettlementName] = createSignal<string>("");
	const [playerName, setPlayerName] = createSignal<string>("");

	createEffect(() => {
		if (props.leaderId === PlayerIds.NO_PLAYER) {
			return;
		}

		const player = Players.get(props.leaderId);
		if (!player) {
			return;
		}
		setPlayerName(Locale.compose(player.name));
		const variants = getPlayerColorVariants(props.leaderId);

		if (variants) {
			setBannerColor(variants.primaryColor.moreColor);
		}
		if (props.cityId) {
			const iconProperities = getSettlementIconInfo(props.cityId);
			if (iconProperities) {
				setCivSymbol(iconProperities.icon);
				setCivSymbolColor(iconProperities.color);
			}
			const city = Cities.get(props.cityId);
			if (city) {
				setSettlementName(Locale.compose(city.name));
			}
		} else {
			setCivSymbol(Icon.getCivSymbolFromCivilizationType(player.civilizationType));
		}
	});

	return (
		<div
			class="z-0 relative flex flex-col items-center justify-center"
			classList={{
				"primary-color-is-lighter": isPrimaryColorLighter(props.leaderId),
				"local-player": props.leaderId === GameContext.localPlayerID,
			}}
			data-name="PlotTooltipPlayerPortrait"
		>
			<Show
				when={props.representsCityState}
				fallback={
					<PortraitIcon
						playerId={props.leaderId}
						size={12}
					/>
				}
			>
				<Tooltip.Text
					header="LOC_CIVILIZATION_CITY_STATE_NAME"
					text="LOC_COMMERCE_TRADE_ROUTE_CITY_STATE_TOOLTIP"
					args={[settlementName(), playerName()]}
				>
					<PortraitIcon
						playerId={props.leaderId}
						size={11}
					/>
				</Tooltip.Text>
			</Show>
			<Show when={props.showBanner}>
				<div class="-z-1 relative h-16 w-9 flex-1 flex flex-row justify-center mx-1.5 -mt-8">
					<div
						class="absolute inset-0"
						style={{
							"border-image-slice": "40 31 31 31 fill",
							"border-image-width": `${Layout.pixels(40)} ${Layout.pixels(31)} ${Layout.pixels(31)} ${Layout.pixels(31)}`,
							"border-image-source": "url(blp:hud_frontbanner)",
							// eslint-disable-next-line solid/style-prop
							"fxs-border-image-tint": props.representsCityState ? "white" : bannerColor(),
						}}
					/>
					<div
						class="absolute inset-0"
						style={{
							"border-image-source": "url('blp:hud_frontbanner_shadow')",
							"border-image-slice": "40 31 31 31 fill",
							"border-image-width": `${Layout.pixels(40)} ${Layout.pixels(31)} ${Layout.pixels(31)} ${Layout.pixels(31)}`,
						}}
					/>
					<div
						class="absolute inset-0"
						style={{
							"border-image-source": "url('blp:hud_frontbanner_overlay')",
							"border-image-slice": "1 31 29 31 fill",
							"border-image-width": `${Layout.pixels(1)} ${Layout.pixels(31)} ${Layout.pixels(29)} ${Layout.pixels(31)}`,
						}}
					/>
					<div
						class="bg-contain bg-center bg-no-repeat relative self-end mb-3 size-6"
						style={{
							"background-image": civSymbol().startsWith("url") ? civSymbol() : `url('${civSymbol()}')`,
							// eslint-disable-next-line solid/style-prop
							"fxs-background-image-tint": civSymbolColor(),
						}}
					/>
				</div>
			</Show>
		</div>
	);
};
